
import 'jquery';
import 'jquery-mask-plugin';
// Since jQuery's type defintion is no module we cant re-export typings. 
// We need to rename the namespace, or we can't export it using the same name in SigUtils.
import _JQuery = JQuery

declare global {
    /** 
    * This namespace is used to encapsulate all provided Utils libraries.
    */
    namespace SigUtils {
        /**
        * jQuery is a fast, small, and feature-rich JavaScript library.
        */
        export import JQuery = _JQuery
    }
    // NOTE: The jQuery typings already declare constants
    // for 'jQuery' and '$' in the global scope. 
    // Therefore we can't re-declare or delete them. 
    // So, we only extend the Window interface.
    interface Window {
        /**
        * jQuery is a fast, small, and feature-rich JavaScript library.
        */
        jQuery: JQueryStatic
        /**
         * This is a shorthand of window.jQuery.
         */
        $: JQueryStatic
    }
}
